{"output":"1\t#!/usr/bin/env bash\n2\t# collect_tomcat.sh - 采集 Tomcat 9 tar.gz（硬性要求 9 系列，10.x/11.x 一律拒绝）\n3\t\n4\tset -Eeuo pipefail\n5\tSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\n6\tsource \"${SCRIPT_DIR}/lib.sh\"\n7\t\n8\tFAMILY=\"${TARGET_FAMILY:-$(auto_detect_family)}\"\n9\tARCH_VAL=\"${TARGET_ARCH:-$(auto_detect_arch)}\"\n10\tcase \"${ARCH_VAL}\" in\n11\t    x86_64|aarch64) : ;;\n12\t    *) die \"${EX_USAGE}\" \"仅支持 x86_64 / aarch64（Tomcat 本身跨架构，此限制与 JDK/MySQL 对齐），当前架构：${ARCH_VAL}\" ;;\n13\tesac\n14\t\n15\tOUT_DIR=\"${PKG_DIR}/${FAMILY}/${ARCH_VAL}/tomcat\"\n16\tmkdir -p \"${OUT_DIR}\"\n17\t\n18\t# 版本硬性要求：Tomcat 9.x（可用环境变量 TOMCAT_VERSION 覆盖小版本，仍必须在 9 系列内）\n19\tTOMCAT_VERSION=\"${TOMCAT_VERSION:-9.0.91}\"\n20\tcase \"${TOMCAT_VERSION}\" in\n21\t    9.*) : ;;\n22\t    *) die \"${EX_USAGE}\" \"Tomcat 版本硬性要求 9 系列，当前配置：${TOMCAT_VERSION}\" ;;\n23\tesac\n24\t\n25\t# 双重校验：以包内容（tar 顶层目录）识别真实版本，文件名不做要求——\n26\t# 现场投喂的包可能叫 tomcat.zip、tomcat-test.tar.gz 等任意名字，实际是 9.0.132 也照样收录；\n27\t# gzip -t / unzip -t 全量完整性校验（残卷/截断包必失败）\n28\tcheck_tomcat_tarball() {\n29\t    local f=\"$1\"\n30\t    case \"${f}\" in\n31\t        *.zip)\n32\t            if have_cmd unzip; then\n33\t                unzip -tqq \"${f}\" >/dev/null 2>&1 || { err \"zip 归档不完整（unzip 校验失败）：$(basename \"${f}\")\"; return 1; }\n34\t            elif have_cmd python3; then\n35\t                python3 -c 'import sys, zipfile\n36\tsys.exit(1 if zipfile.ZipFile(sys.argv[1]).testzip() else 0)' \"${f}\" 2>/dev/null \\\n37\t                    || { err \"zip 归档不完整（python 校验失败）：$(basename \"${f}\")\"; return 1; }\n38\t            else\n39\t                err \"缺少 unzip/python3，无法校验 .zip 包（可用 tar.gz 代替）：$(basename \"${f}\")\"\n40\t                return 1\n41\t            fi\n42\t            ;;\n43\t        *)\n44\t            gzip -t \"${f}\" 2>/dev/null || { err \"tarball 不完整（gzip 校验失败）：$(basename \"${f}\")\"; return 1; }\n45\t            ;;\n46\t    esac\n47\t    local top\n48\t    top=\"$(archive_top_entry \"${f}\")\"\n49\t    top=\"${top#./}\"\n50\t    case \"${top}\" in\n51\t        apache-tomcat-9.*|tomcat-9.*) : ;;\n52\t        *) err \"Tomcat 硬性要求 9 系列（包内容顶层目录：${top:-无法识别}），拒绝收录：$(basename \"${f}\")\"; return 1 ;;\n53\t    esac\n54\t    return 0\n55\t}\n56\t\n57\t# 从归档内容提取具体版本号（如 9.0.132），仅用于日志展示\n58\ttomcat_version_of() {\n59\t    local top\n60\t    top=\"$(archive_top_entry \"$1\")\"\n61\t    printf '%s' \"${top}\" | grep -oE '9\\.[0-9]+(\\.[0-9]+)?' | head -n1 || true\n62\t}\n63\t\n64\t# 本地优先（仍须满足 9 系列，不符合则直接报错退出，不静默收录）。\n65\t# 文件名任意（tomcat.zip、apache-tomcat-*.tar.gz 均可），版本以包内容为准。\n66\tshopt -s nullglob\n67\tfor d in \"${HOME}\" /opt /usr/local; do\n68\t    for cand in \"${d}\"/apache-tomcat*.tar.gz \"${d}\"/apache-tomcat*.zip \\\n69\t                \"${d}\"/tomcat*.tar.gz \"${d}\"/tomcat*.zip; do\n70\t        [[ -f \"${cand}\" ]] || continue\n71\t        if check_tomcat_tarball \"${cand}\"; then\n72\t            cp -n \"${cand}\" \"${OUT_DIR}/\"\n73\t            info \"已复制本地 Tomcat: ${cand}（包内实际版本：$(tomcat_version_of \"${cand}\" || echo 未知)）\"\n74\t            exit 0\n75\t        else\n76\t            die \"${EX_USAGE}\" \"本地 Tomcat 包不符合 9 系列硬性要求，请替换为 apache-tomcat-9.x 归档后重试：${cand}\"\n77\t        fi\n78\t    done\n79\tdone\n80\tshopt -u nullglob\n81\t\n82\t# 已有完整包则跳过（以包内容校验，文件名任意）\n83\tEXISTING=\"$(find \"${OUT_DIR}\" -maxdepth 1 -type f \\( -name '*.tar.gz' -o -name '*.zip' \\) -size +5M 2>/dev/null | head -n1)\"\n84\tif [[ -n \"${EXISTING}\" ]] && check_tomcat_tarball \"${EXISTING}\"; then\n85\t    ok \"Tomcat 已存在且校验通过，跳过下载：${EXISTING}（包内实际版本：$(tomcat_version_of \"${EXISTING}\" || echo 未知)）\"\n86\t    exit 0\n87\tfi\n88\t\n89\tREL_PATH=\"tomcat/tomcat-9/v${TOMCAT_VERSION}/bin/apache-tomcat-${TOMCAT_VERSION}.tar.gz\"\n90\tOUT_FILE=\"${OUT_DIR}/apache-tomcat-${TOMCAT_VERSION}.tar.gz\"\n91\tinfo \"下载 Tomcat ${TOMCAT_VERSION}（断点续传，最多 3 轮重试）\"\n92\t# 国内镜像优先（阿里云），archive.apache.org 兜底\n93\tURLS=(\n94\t    \"https://mirrors.aliyun.com/apache/${REL_PATH}\"\n95\t    \"https://archive.apache.org/dist/${REL_PATH}\"\n96\t)\n97\tDL_OK=0\n98\tfor url in \"${URLS[@]}\"; do\n99\t    for _try in 1 2 3; do\n100\t        _ec=0\n101\t        curl -fsSL --retry 2 --retry-delay 3 -C - \"${url}\" -o \"${OUT_FILE}\" && _ec=0 || _ec=$?\n102\t        if [[ ${_ec} -eq 0 ]] && check_tomcat_tarball \"${OUT_FILE}\"; then\n103\t            DL_OK=1\n104\t            break 2\n105\t        fi\n106\t        # 退出码 22 = HTTP 错误（如 404）：镜像站只保留各大版本的最新发布版，\n107\t        # 旧版本（如 9.0.91）只在 archive.apache.org 上存在，重试必然还是 404，\n108\t        # 立即换下一个 URL；其余退出码（超时/传输中断）才是值得断点续传的暂态错误。\n109\t        if [[ ${_ec} -eq 22 ]]; then\n110\t            warn \"${url} 返回 HTTP 错误（该镜像无此版本，属永久性 404），换下一个源\"\n111\t            break\n112\t        fi\n113\t        warn \"下载中断（${url} 第 ${_try}/3 轮），断点续传重试中...\"\n114\t        sleep 3\n115\t    done\n116\tdone\n117\tif [[ \"${DL_OK}\" -ne 1 ]]; then\n118\t    warn \"下载失败（需人工准备 apache-tomcat-9.x tarball 放到 ${OUT_DIR}/）\"\n119\t    exit 0\n120\tfi\n121\tok \"Tomcat 已就绪：${OUT_FILE}\""}